<?php require_once __DIR__ . '/includes/db.php'; require_once __DIR__ . '/includes/functions.php'; $pdo=db(); $st=$pdo->prepare("SELECT * FROM galleries WHERE slug=? AND status='published'"); $st->execute([$_GET['slug']??'']); $g=$st->fetch(); if(!$g) die('Gallery not found.'); $st=$pdo->prepare('SELECT * FROM gallery_images WHERE gallery_id=? ORDER BY sort_order,id'); $st->execute([$g['id']]); $imgs=$st->fetchAll(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/css/style.css"><title><?=h($g['title'])?></title></head><body class="museum-body"><header class="site-header site-header-compact"><a class="brand-lockup" href="index.php"><div class="logo-mark" aria-hidden="true"></div><div><div class="logo"><span>taos</span>arts.org</div><p class="brand-tag">Curated rooms and visual collections</p></div></a><nav class="nav"><a href="index.php">Home</a><a href="index.php#meetings">Meetings</a><a href="index.php#stories">Stories</a><a href="index.php#galleries">Galleries</a></nav></header><main><section class="section gallery-page"><a class="text-link" href="index.php">← Back to home</a><div class="page-intro"><p class="eyebrow">Gallery Room</p><h1><?=h($g['title'])?></h1><p><?=h($g['description'])?></p></div><div class="gallery-grid gallery-page-grid"><?php foreach($imgs as $index => $im): ?><figure class="card museum-card gallery-tile<?= $index === 0 ? ' gallery-tile-featured' : '' ?>"><div class="thumb"><img src="<?=h($im['file_path'])?>" alt="<?=h($im['alt_text'])?>"></div><figcaption><?=h($im['caption'])?></figcaption></figure><?php endforeach; ?></div></section></main></body></html>
